INSERT INTO content_records (id,kind,status,source,updated_at,sort_order,payload) VALUES ('a-station-in-daily-life','articles','published','使用者2026-10-17要求參照官方社群完成圖文與SEO；來源詳見docs/journal-seo-2026-10-17.md','2026-10-17',56,'{"slug":"a-station-in-daily-life","category":"鐵道文史","title":"日南車站：從木造站房、牛眼窗，讀懂海線的往返日常","summary":"臺中大甲的日南車站，是海線仍在使用的木造古蹟車站。從牛眼窗、月台與地方生活認識日南，再走到車站旁的日南稻站，讓一趟海線小旅行多一點停留。","cover":{"src":"/images/stories/station-front-800.webp","width":800,"height":533,"alt":"日南車站木造站房、站名與山牆上的圓形牛眼窗","credit":"臺中市文化資產處（資料照片）","sourceUrl":"https://www.tchac.taichung.gov.tw/building?pid=22&uid=33","variants":[{"src":"/images/stories/station-front-640.webp","width":640},{"src":"/images/stories/station-front-800.webp","width":800}]},"imageCredit":"臺中市文化資產處（資料照片）","image":"/images/stories/station-front-800.webp","imageAlt":"日南車站木造站房、站名與山牆上的圓形牛眼窗","readingMinutes":4,"sourceLabel":"臺中市文化資產處與日南稻站官方社群","sourceUrl":"","sources":[{"label":"臺中市文化資產處｜縱貫鐵路海線．日南車站","url":"https://www.tchac.taichung.gov.tw/building?pid=22&uid=33"},{"label":"日南稻站 Instagram｜從這裡出發，也從這裡回來（2026.08.25）","url":"https://www.instagram.com/p/Dcd-nEsyKIX/"},{"label":"日南稻站 Instagram｜換個角度看日南（2026.08.27）","url":"https://www.instagram.com/p/DcjGHeWSWEY/"}],"sections":[{"heading":"日南車站在哪裡？從臺中大甲的海線小站開始","text":"日南車站位於臺中市大甲區，是認識日南的一個起點。第一次抵達，視線可能先停在木造站房與「日南」兩字；對住在這裡的人來說，這裡也連著上學、工作、接送，以及回家的路。把車站放回地方生活裡看，一次到訪就能多出幾個問題：人們從這裡去哪裡？又為了什麼回來？這些往返，也是我們整理地方筆記時想留下的故事。"},{"heading":"日南車站的歷史：海線鐵路與市定古蹟","text":"依臺中市文化資產處資料，西部縱貫線中段的海線從竹南經大甲至彰化，於 1919 年開工、1922 年完工。日南車站保存海線標準型木造站房，並於 2002 年 11 月 26 日公告為市定古蹟。閱讀這些年代，可以把眼前的站房放進鐵道發展的時間裡；走到現場，則能再看看這座建築如何與今天的交通、街道和生活相接。"},{"heading":"看日南車站，可以留意哪些建築細節？","text":"牛眼窗是日南車站很容易辨認的細節。從月台一側望向站房高處，可以看見山牆上的圓形窗；把視線往下移，木構、屋簷與站名也在同一個畫面裡。與其急著拍完整座車站，不妨分別看一扇窗、一段屋簷，再看站房和月台的距離。參觀時請依車站動線與現場規定通行，保留旅客進出和候車的空間。","images":[{"src":"/images/stories/station-platform-800.webp","width":800,"height":533,"alt":"日南車站月台一側的木造站房與鐵道","credit":"臺中市文化資產處（資料照片）","sourceUrl":"https://www.tchac.taichung.gov.tw/building?pid=22&uid=33","variants":[{"src":"/images/stories/station-platform-640.webp","width":640},{"src":"/images/stories/station-platform-800.webp","width":800}]}]},{"heading":"從車站往外看：田野、聚落與日南人的生活","text":"日南稻站的社群曾從日常的視角介紹這裡：人們從車站出發，也從車站回來；田裡有稻與芋頭，周邊有工廠、聚落與信仰。空拍把平常一段段經過的路放進同一張照片，讓田野和海岸的關係變得清楚。對初訪的人，車站是一個好辨認的入口；對在地人，這些景色則是每天生活的一部分。","images":[{"src":"/images/stories/rinan-aerial-1350.webp","width":1350,"height":1688,"alt":"日南田野、聚落與海岸的空拍社群圖文","credit":"日南稻站官方 Instagram｜攝影：字語影像 @zifilm.tw","sourceUrl":"https://www.instagram.com/p/DcjGHeWSWEY/","variants":[{"src":"/images/stories/rinan-aerial-640.webp","width":640},{"src":"/images/stories/rinan-aerial-1350.webp","width":1350}]}]},{"heading":"海線小旅行，從日南車站延伸到日南稻站","text":"走出車站，可以接著認識旁邊的日南稻站。這個地方文化據點正在整理空間、展覽與人物故事，邀請路過的人停一下，也讓在外生活的人有一個重新認識家鄉的入口。你可以先讀陳隆安、鄭筱萱與娜翎的故事，再用九里互動地圖理解周邊聚落的位置；想安排實際到訪，則以交通頁與最新開放公告為準。","links":[{"label":"認識日南稻站的空間故事","href":"/stories/a-place-to-stop/"},{"label":"閱讀走傱的日南人","href":"/stories/?category=people"},{"label":"走進日南九里互動地圖","href":"/explore/"}]},{"heading":"到訪前，先確認交通與開放資訊","text":"日南車站與日南稻站是相鄰的不同場所：前者是鐵路車站，後者是地方文化據點。搭車前請查詢臺鐵當日列車資訊；若也想進入稻站看展或參加活動，請另確認稻站公告。社群裡的車站印象適合當作認識地方的開頭，實際行程仍要按當日班次與開放安排規劃。這一次，在日南下車，留一點時間看看平常會經過的地方。","links":[{"label":"查看到訪交通與稻站導航","href":"/visit/"},{"label":"查看走傱日南 2026 活動資訊","href":"/motion2026/"}]}]}');
INSERT INTO content_records (id,kind,status,source,updated_at,sort_order,payload) VALUES ('a-place-to-stop','articles','published','使用者2026-10-17要求參照官方社群完成圖文與SEO；來源詳見docs/journal-seo-2026-10-17.md','2026-10-17',57,'{"slug":"a-place-to-stop","category":"空間日常","title":"日南稻站：打開車站旁的舊營房，留一個可以停一下的地方","summary":"日南稻站位於臺中大甲日南車站旁，從舊營房重新整理成地方文化據點。透過展覽、交流與地方故事，邀請居民、返鄉的人與初訪旅人，在往返之間重新認識日南。","cover":{"src":"/images/stories/rinan-aerial-1350.webp","width":1350,"height":1688,"alt":"日南田野、聚落與海岸的空拍社群圖文","credit":"日南稻站官方 Instagram｜攝影：字語影像 @zifilm.tw","sourceUrl":"https://www.instagram.com/p/DcjGHeWSWEY/","variants":[{"src":"/images/stories/rinan-aerial-640.webp","width":640},{"src":"/images/stories/rinan-aerial-1350.webp","width":1350}]},"imageCredit":"日南稻站官方 Instagram｜攝影：字語影像 @zifilm.tw","image":"/images/stories/rinan-aerial-1350.webp","imageAlt":"日南田野、聚落與海岸的空拍社群圖文","readingMinutes":4,"sourceLabel":"日南稻站｜空間紀錄與官方社群","sourceUrl":"","sources":[{"label":"日南稻站 Instagram｜邀你在日南停一下（2026.08.31）","url":"https://www.instagram.com/p/DctLYv4S7Go/"},{"label":"日南稻站 Instagram｜日南的稻田與芋田（2026.08.29）","url":"https://www.instagram.com/p/DcoQGWoy9z-/"},{"label":"日南稻站 Instagram｜這一次，就在日南下車吧（2026.09.12）","url":"https://www.instagram.com/p/DdL76E9D0Ar/"}],"sections":[{"heading":"日南稻站是什麼？車站旁的地方文化據點","text":"日南稻站 Rinan Commons 位於臺中大甲的日南車站旁，是一個從地方生活出發的文化據點。我們想整理的，有車站與土地的故事，也有人們離鄉、返鄉、留下，或第一次來到日南的經驗。對外地旅人，這裡可以是認識日南的開頭；對住在附近的人，我們希望它逐漸成為生活裡能停一下、遇見彼此的地方。"},{"heading":"把關了很久的舊軍營，慢慢打開","text":"日南稻站所在的空間原是舊營房。2026 年 8 月的開幕預告裡，我們寫下想把關了很久的舊軍營打開，讓人可以走進來。整理空間時，我們採取最小介入、可逆式改善的方向，讓新的使用方式慢慢進入原有建築。空間重新開放之後，最想迎接的是平常就在這裡生活的人，以及一路走傱後又回到日南的人。","images":[{"src":"/images/stories/rinan-motion-1350.webp","width":1350,"height":1688,"alt":"日南稻站開幕預告圖文：為了生活，我們不停移動","credit":"日南稻站官方 Instagram｜攝影：字語影像 @zifilm.tw","sourceUrl":"https://www.instagram.com/p/DctLYv4S7Go/","variants":[{"src":"/images/stories/rinan-motion-640.webp","width":640},{"src":"/images/stories/rinan-motion-1350.webp","width":1350}]}]},{"heading":"放學、下班、等火車，都能想起一個停留的所在","text":"我們在社群裡描繪過幾個簡單的畫面：居民運動後進來休息，放學或下班後坐一下，返鄉的人偶爾聚在一起聊近況。這些是稻站對空間日常的期待，也會隨著開放和使用逐步形成。地方文化可以從一段聊天、一張舊照片開始；有人願意分享，就有機會讓原本各自熟悉的日南，被更多人一起認識。"},{"heading":"為什麼從稻田、芋田與地方生活說起？","text":"從田埂望出去，細密的稻葉和寬大的芋葉，構成日南熟悉的農作風景。社群以「一塊田的兩邊，稻和芋頭」記錄這些日常，也提醒我們換個角度看習以為常的地方。稻站的內容從這裡延伸：田裡的作物、在地人的工作、聚落裡的相遇，都可以成為展覽與交流的題材。想進一步認識植物，也可以先到網站的日南植物形態室，觀察稻米、芋頭與其他地方植物。","images":[{"src":"/images/stories/rinan-fields-1350.webp","width":1350,"height":1688,"alt":"日南水稻與芋頭田的社群圖文","credit":"日南稻站官方 Instagram","sourceUrl":"https://www.instagram.com/p/DcoQGWoy9z-/","variants":[{"src":"/images/stories/rinan-fields-640.webp","width":640},{"src":"/images/stories/rinan-fields-1350.webp","width":1350}]}],"links":[{"label":"探索日南植物形態室","href":"/plants/"},{"label":"讀陳隆安與日南稻田的故事","href":"/stories/people-chen-long-an/"}]},{"heading":"從《往返》展覽與人物故事，認識日南","text":"《往返 TO AND FROM》以走傱、返回與生根的經驗，連起人和地方的關係。你可以先在線上閱讀展覽介紹，再接著看《走傱的日南人》：陳隆安在田裡耕作、守著家；鄭筱萱從日南出發，帶著臺灣的宮廟文化往外走；娜翎從泰國來到日南，在這裡成家與創業。三種不同的生活，讓我們繼續思考，日南如何成為一個人的家鄉。","links":[{"label":"閱讀《往返》展覽手冊","href":"/exhibition/to-and-from/"},{"label":"閱讀三位日南人的完整故事","href":"/stories/?category=people"}]},{"heading":"日南稻站在哪裡？現在可以怎麼安排到訪？","text":"日南稻站在日南車站旁，地址指引為臺中市大甲區孟春里中山路二段 1 號對面，可由本站交通頁開啟據點導航。2026 年 10 月 24、25 日的「走傱日南 2026」，將串連稻站與日南車站旁廣場，邀請大家透過展覽、交流、音樂與市集來認識地方。日常固定開放時間將另行公告；出發前，請查看活動頁及官方社群的最新資訊。","links":[{"label":"查看到訪交通與據點導航","href":"/visit/"},{"label":"查看走傱日南 2026 完整活動","href":"/motion2026/"},{"label":"追蹤日南稻站 Facebook","href":"https://www.facebook.com/rinan.commons/"},{"label":"追蹤日南稻站 Instagram","href":"https://www.instagram.com/rinan.commons/"}]}]}');
