INSERT INTO content_records (id,kind,status,source,updated_at,sort_order,payload) VALUES ('people-chen-long-an','articles','published','使用者 2026-10-17 提供全文與人物故事集照片，明確要求公開於地方筆記','2026-10-17',58,'{"slug":"people-chen-long-an","category":"人物故事","title":"走傱的日南人 1｜陳隆安","summary":"種著田、守著家，也成為下一代安心從家鄉出發、往外走傱的依靠。","image":"/images/stories/chen-long-an-08-1440.webp","imageAlt":"陳隆安走過一片綠色稻田","readingMinutes":3,"sourceLabel":"日南稻站｜走傱的日南人","sourceUrl":"","imageCredit":"日南稻站提供｜走傱的日南人","cover":{"src":"/images/stories/chen-long-an-08-1440.webp","width":2048,"height":1366,"alt":"陳隆安走過一片綠色稻田","variants":[{"src":"/images/stories/chen-long-an-08-640.webp","width":640},{"src":"/images/stories/chen-long-an-08-1440.webp","width":1439}]},"seriesNumber":1,"personName":"陳隆安","sections":[{"heading":"","text":"日南車站在日治時期曾是日本天皇御用稻米的集散地，百年後，在這片孕育稻作的土地上，有一位順著地方的風土，種出日南絕頂好米的在地稻農——陳隆安。","images":[{"src":"/images/stories/chen-long-an-01-1440.webp","width":2048,"height":1536,"alt":"陳隆安走在聚落旁的稻田裡","variants":[{"src":"/images/stories/chen-long-an-01-640.webp","width":640},{"src":"/images/stories/chen-long-an-01-1440.webp","width":1440}]}]},{"heading":"","text":"陳隆安棄工從農，從父親手中接下種稻的技藝，耕作二十餘年，拿下日本第十二屆「米・食味分析鑑定國際大賞」特別優秀賞，更是全國十大經典好米四冠王得主。","images":[{"src":"/images/stories/chen-long-an-02-1440.webp","width":2048,"height":1366,"alt":"陳隆安戴著斗笠在田間工作","variants":[{"src":"/images/stories/chen-long-an-02-640.webp","width":640},{"src":"/images/stories/chen-long-an-02-1440.webp","width":1439}]},{"src":"/images/stories/chen-long-an-07-1440.webp","width":2048,"height":1366,"alt":"陳隆安彎身照料稻田","variants":[{"src":"/images/stories/chen-long-an-07-640.webp","width":640},{"src":"/images/stories/chen-long-an-07-1440.webp","width":1439}]}]},{"heading":"","text":"他選擇在日南成家、務農，順應自然、友善土地，發展友善耕作法：手工除草、維持田間生態；與經營東興香品行的妻子羅美玉，在這裡養育三名兒女長大。家裡的一片片稻田，始終牽繫著一家人與日南之間的家鄉情感。","images":[{"src":"/images/stories/chen-long-an-04-1440.webp","width":2048,"height":1366,"alt":"陳隆安在樹林旁整理農務","variants":[{"src":"/images/stories/chen-long-an-04-640.webp","width":640},{"src":"/images/stories/chen-long-an-04-1440.webp","width":1439}]}]},{"heading":"","text":"現在，陳隆安依然在日南，在這裡落地生根，種著田、守著家，也成為下一代安心從家鄉出發、往外走傱的依靠。","images":[{"src":"/images/stories/chen-long-an-03-1440.webp","width":2048,"height":1366,"alt":"陳隆安坐在樹蔭下","variants":[{"src":"/images/stories/chen-long-an-03-640.webp","width":640},{"src":"/images/stories/chen-long-an-03-1440.webp","width":1439}]},{"src":"/images/stories/chen-long-an-06-1440.webp","width":1366,"height":2048,"alt":"陳隆安坐在樹下的直幅紀錄照","variants":[{"src":"/images/stories/chen-long-an-06-640.webp","width":640},{"src":"/images/stories/chen-long-an-06-1440.webp","width":1366}]},{"src":"/images/stories/chen-long-an-05-1440.webp","width":2048,"height":1366,"alt":"稻葉間彎身工作的陳隆安","variants":[{"src":"/images/stories/chen-long-an-05-640.webp","width":640},{"src":"/images/stories/chen-long-an-05-1440.webp","width":1439}]}]}]}');
INSERT INTO content_records (id,kind,status,source,updated_at,sort_order,payload) VALUES ('people-cheng-hsiao-hsuan','articles','published','使用者 2026-10-17 提供全文與人物故事集照片，明確要求公開於地方筆記','2026-10-17',59,'{"slug":"people-cheng-hsiao-hsuan","category":"人物故事","title":"走傱的日南人 2｜鄭筱萱","summary":"這位從日南出發的查某囝，帶著臺灣的宮廟文化走向更遠的世界；而這擺，她要帶著震樂堂回娘家了。","image":"/images/stories/cheng-hsiao-hsuan-04-1440.webp","imageAlt":"鄭筱萱站在日南車站月台出口","readingMinutes":3,"sourceLabel":"日南稻站｜走傱的日南人","sourceUrl":"","imageCredit":"日南稻站提供｜走傱的日南人","cover":{"src":"/images/stories/cheng-hsiao-hsuan-04-1440.webp","width":2048,"height":1366,"alt":"鄭筱萱站在日南車站月台出口","variants":[{"src":"/images/stories/cheng-hsiao-hsuan-04-640.webp","width":640},{"src":"/images/stories/cheng-hsiao-hsuan-04-1440.webp","width":1439}]},"seriesNumber":2,"personName":"鄭筱萱","sections":[{"heading":"","text":"如同許多日南青年一般，日南國中畢業後，鄭筱萱便從車站出發，向外走傱。一路從臺中女中到中山大學劇場藝術學系，她逐漸走上一條與家鄉成長經驗截然不同的道路。","images":[{"src":"/images/stories/cheng-hsiao-hsuan-03-1440.webp","width":2048,"height":1366,"alt":"鄭筱萱坐在列車窗邊","variants":[{"src":"/images/stories/cheng-hsiao-hsuan-03-640.webp","width":640},{"src":"/images/stories/cheng-hsiao-hsuan-03-1440.webp","width":1439}]}]},{"heading":"","text":"如今，她擔任臺灣本土宮廟搖滾樂團「震樂堂」的經紀人，與樂團一同帶著臺灣民間信仰的文化底蘊，走傱到捷克、新加坡、日本新潟 Fuji Rock 音樂祭，也登上今年的總統府音樂會。而我們的鏡頭，也在今年七月跟著她來到東京，紀錄這場海外售票演出的幕後工作與舞台現場。","images":[{"src":"/images/stories/cheng-hsiao-hsuan-02-1440.webp","width":2048,"height":1368,"alt":"鄭筱萱與震樂堂在機場合影","variants":[{"src":"/images/stories/cheng-hsiao-hsuan-02-640.webp","width":640},{"src":"/images/stories/cheng-hsiao-hsuan-02-1440.webp","width":1440}]},{"src":"/images/stories/cheng-hsiao-hsuan-01-1440.webp","width":2048,"height":1368,"alt":"鄭筱萱與震樂堂在舞台上的合影","variants":[{"src":"/images/stories/cheng-hsiao-hsuan-01-640.webp","width":640},{"src":"/images/stories/cheng-hsiao-hsuan-01-1440.webp","width":1440}]},{"src":"/images/stories/cheng-hsiao-hsuan-05-1440.webp","width":2048,"height":1152,"alt":"震樂堂的演出舞台與燈光","variants":[{"src":"/images/stories/cheng-hsiao-hsuan-05-640.webp","width":640},{"src":"/images/stories/cheng-hsiao-hsuan-05-1440.webp","width":1440}]},{"src":"/images/stories/cheng-hsiao-hsuan-06-1440.webp","width":1350,"height":770,"alt":"鄭筱萱在舞台前看著演出現場","variants":[{"src":"/images/stories/cheng-hsiao-hsuan-06-640.webp","width":640},{"src":"/images/stories/cheng-hsiao-hsuan-06-1440.webp","width":1350}]}]},{"heading":"","text":"留在日南的阿爸鄭清海、阿母王美鳳，長年在這片土地投入生態教育，也每年到慈德宮為兒女點燈祈福。這位從日南出發的查某囝，帶著臺灣的宮廟文化走向更遠的世界；而這擺，她要帶著震樂堂回娘家了。","images":[{"src":"/images/stories/cheng-hsiao-hsuan-07-1440.webp","width":1724,"height":1152,"alt":"鄭筱萱與家人在家中合影","variants":[{"src":"/images/stories/cheng-hsiao-hsuan-07-640.webp","width":640},{"src":"/images/stories/cheng-hsiao-hsuan-07-1440.webp","width":1440}]}]}]}');
INSERT INTO content_records (id,kind,status,source,updated_at,sort_order,payload) VALUES ('people-narin','articles','published','使用者 2026-10-17 提供全文與人物故事集照片，明確要求公開於地方筆記','2026-10-17',60,'{"slug":"people-narin","category":"人物故事","title":"走傱的日南人 3｜娜翎 Narin","summary":"從泰國走傱到日南，娜翎在這裡成家、創業，也陪伴更多離鄉的人，在異鄉建立新的生活。","image":"/images/stories/narin-06-1440.webp","imageAlt":"娜翎在店裡翻看資料","readingMinutes":3,"sourceLabel":"日南稻站｜走傱的日南人","sourceUrl":"","imageCredit":"日南稻站提供｜走傱的日南人","cover":{"src":"/images/stories/narin-06-1440.webp","width":2048,"height":1366,"alt":"娜翎在店裡翻看資料","variants":[{"src":"/images/stories/narin-06-640.webp","width":640},{"src":"/images/stories/narin-06-1440.webp","width":1439}]},"seriesNumber":3,"personName":"娜翎 Narin","sections":[{"heading":"","text":"位於大甲日南的幼獅產業園區，是中部重要的製造業與精密機械產業聚落，也吸引來自不同國家的移工在此工作、生活，為日南帶來不同的語言、飲食與文化。來自泰國的娜翎（Narin），就是其中一位在日南展開人生新旅程的人。","images":[{"src":"/images/stories/narin-05-1440.webp","width":2048,"height":1366,"alt":"朋友們在木屋用餐區聚餐","variants":[{"src":"/images/stories/narin-05-640.webp","width":640},{"src":"/images/stories/narin-05-1440.webp","width":1439}]}]},{"heading":"","text":"娜翎在異鄉工作的日子裡，結識了現在的先生趙壬章，兩人決定在日南成家、創業，共同經營「娜翎の窩（Thai Narin）」。從販售泰國食品與生活用品開始，逐漸發展成結合泰式料理、日常採買與生活服務的空間，也成為許多泰國朋友相聚、交流的地方。","images":[{"src":"/images/stories/narin-01-1440.webp","width":2048,"height":1366,"alt":"娜翎與先生在店內整理貨品","variants":[{"src":"/images/stories/narin-01-640.webp","width":640},{"src":"/images/stories/narin-01-1440.webp","width":1439}]},{"src":"/images/stories/narin-03-1440.webp","width":1366,"height":2048,"alt":"娜翎與先生站在娜翎の窩店門前","variants":[{"src":"/images/stories/narin-03-640.webp","width":640},{"src":"/images/stories/narin-03-1440.webp","width":1366}]}]},{"heading":"","text":"娜翎的父親也遠從泰國來到日南，利用廢棄木料，在店外親手搭起一座座傳統泰式高腳木屋，成為餐廳的用餐區。這些充滿家鄉風味的空間，不只承載著娜翎對泰國的生活記憶，也讓許多離鄉工作的泰國朋友，在日南找到熟悉的味道與家的感覺。","images":[{"src":"/images/stories/narin-07-1440.webp","width":2048,"height":1366,"alt":"綠意環繞的泰式高腳木屋","variants":[{"src":"/images/stories/narin-07-640.webp","width":640},{"src":"/images/stories/narin-07-1440.webp","width":1439}]}]},{"heading":"","text":"從泰國走傱到日南，娜翎在這裡成家、創業，也陪伴更多離鄉的人，在異鄉建立新的生活。日南是她夢想的起點，也是她決定安身立命的所在，而她與先生、四名兒女，也成為這片土地的新日南人。","images":[{"src":"/images/stories/narin-02-1440.webp","width":1366,"height":2048,"alt":"娜翎一家人在戶外的合影","variants":[{"src":"/images/stories/narin-02-640.webp","width":640},{"src":"/images/stories/narin-02-1440.webp","width":1366}]},{"src":"/images/stories/narin-04-1440.webp","width":2048,"height":1366,"alt":"娜翎手持麥克風的活動紀錄","variants":[{"src":"/images/stories/narin-04-640.webp","width":640},{"src":"/images/stories/narin-04-1440.webp","width":1439}]}]}]}');
